import type { MapItem, Mcq, Structured, TopoPair } from "./types";

function q(id: string, chapter: string, parts: Structured["parts"]): Structured {
  return { id, chapter, parts };
}

function mcq(
  id: string,
  chapter: string,
  stem: string,
  options: [string, string, string, string],
  answer: 0 | 1 | 2 | 3,
): Mcq {
  return { id, chapter, stem, options, answer };
}

